<script setup lang="ts">
import { svgImageUrl } from '~~/shared/utils/media'
import { useKaban } from '~/composables/useKaban'
import WorkspaceSidebar from '../WorkspaceSidebar.vue'
import PasswordHeader from '../PasswordPage/PasswordHeader.vue'
import KabanCategoryNav from './KabanCategoryNav.vue'
import type { KabanCategory } from '~~/shared/types/kaban'
import PersonAvatar from '../PersonAvatar.vue'
import BoarLogo from '../BoarLogo.vue'
import KabanTaskModal from './KabanTaskModal.vue'
const c=reactive(useKaban()),dragged=ref('')
const taskFormId=useId(),stageFormId=useId(),archiveTarget=ref<KabanCategory|null>(null)
const selected=computed(()=>c.categories.find(category=>category.id===c.selectedCategory))
const selectedParent=computed(()=>c.categories.find(category=>category.id===selected.value?.parentId))
const colors=['#64748b','#6366f1','#3b82f6','#10b981','#f59e0b','#ef4444','#a855f7']
function drop(stageId:string){const task=c.displayData?.tasks.find(task=>task.id===dragged.value);dragged.value='';if(task)void c.moveTask(task,stageId)}
function notification(notification:{entryId:string|null;vaultId:string|null}){navigateTo({path:'/password',query:{...(notification.entryId?{entry:notification.entryId}:{}),...(notification.vaultId?{vault:notification.vaultId}:{})}})}
</script>
<template>
 <div class="vault-shell kaban-shell">
  <WorkspaceSidebar v-model:vault-id="c.workspaceId" :open="c.mobileOpen" section="КАБАН">
   <nav class="vault-nav" aria-label="Задачи"><button :class="{selected:c.view==='board'&&c.selectedCategory==='all'&&!c.onlyMine&&!c.onlyOverdue}" @click="c.setView('board')"><UIcon name="i-lucide-columns-3"/>Доска задач<span class="nav-count">{{c.totalTasks.length}}</span></button><button :class="{selected:c.onlyMine}" @click="c.setView('board');c.onlyMine=true"><UIcon name="i-lucide-user-round-check"/>Мои задачи</button><button :class="{selected:c.onlyOverdue}" @click="c.setView('board');c.onlyOverdue=true"><UIcon name="i-lucide-clock-alert"/>Просроченные</button><button :class="{selected:c.view==='closed'}" @click="c.setView('closed')"><UIcon name="i-lucide-archive"/>Закрытые задачи<span class="nav-count">{{c.totalTasks.filter(task=>task.archived).length}}</span></button><button :class="{selected:c.view==='history'}" @click="c.setView('history')"><UIcon name="i-lucide-history"/>История изменений</button></nav>
   <div class="sidebar-label category-label"><span>КАТЕГОРИИ</span><button v-if="c.canCategorize" aria-label="Создать категорию задач" @click="c.editCategory()"><UIcon name="i-lucide-plus"/></button></div>
   <KabanCategoryNav :categories="c.categories" :active="c.selectedCategory" :count="c.categoryCount" @select="c.chooseCategory"/>
   <div v-if="c.canCategorize" class="kaban-sidebar-actions"><button class="add-category" @click="c.editCategory()"><UIcon name="i-lucide-plus"/>Новая категория</button><button class="add-category" :disabled="!c.categories.some(category=>!category.parentId)" @click="c.editCategory(undefined,selected?.parentId||selected?.id||c.categories.find(category=>!category.parentId)?.id||null)"><UIcon name="i-lucide-folder-plus"/>Новая подкатегория</button></div>
  </WorkspaceSidebar>
  <button v-if="c.mobileOpen" class="sidebar-scrim" aria-label="Закрыть меню" @click="c.mobileOpen=false"/>
  <main class="vault-main"><header class="vault-topbar password-topbar"><PasswordHeader :workspace-name="c.workspaceName" title="Кабан" @toggle-menu="c.mobileOpen=!c.mobileOpen" @open-entry="notification"/></header>
   <div class="vault-content kaban-content">
    <div class="page-heading kaban-heading"><div class="kaban-heading-title"><span class="kaban-logo"><BoarLogo/></span><div><h1>{{c.view==='closed'?'Закрытые задачи':c.view==='history'?'История изменений':'Кабан'}}<span class="title-dot">.</span></h1><p>{{c.workspaceId==='all'?'Задачи из всех доступных хранилищ':selected?`${selectedParent?.name?selectedParent.name+' / ':''}${selected.name}`:'От идеи до готового результата'}}</p></div></div><div class="heading-actions"><UButton v-if="selected&&c.canCategorize" icon="i-lucide-pencil" color="neutral" variant="outline" label="Категория" @click="c.editCategory(selected)"/><UButton v-if="selected&&c.canCategorize" icon="i-lucide-archive" color="neutral" variant="outline" label="Закрыть категорию" :disabled="c.busy" @click="archiveTarget=selected"/><UButton v-if="c.displayData?.canManage" icon="i-lucide-settings-2" color="neutral" variant="outline" label="Стадии" :disabled="c.busy" @click="c.editStages"/><UButton v-if="c.displayData?.canEdit&&c.view==='board'" icon="i-lucide-plus" label="Новая задача" :disabled="c.busy||c.loading" @click="c.openTask()"/></div></div>
    <UAlert v-if="c.error" color="error" :description="c.error" :actions="[{label:'Обновить доску',onClick:()=>c.load()}]" class="mb-5"/>
    <UAlert v-if="c.shared.error" color="error" :description="c.shared.error" class="mb-5"/>
    <div v-if="c.workspaceId==='all'" class="kaban-board-picker"><p>Показаны задачи всех хранилищ. Выберите хранилище, чтобы открыть его доску отдельно.</p><div><button v-for="source in c.visibleSources" :key="source.id" @click="c.workspaceId=source.id"><img v-if="source.data.svg" :src="svgImageUrl(source.data.svg)" class="vault-display-image" alt=""/><UIcon v-else :name="source.id==='personal'?'i-lucide-user-round':'i-lucide-vault'"/><span><strong>{{source.name}}</strong><small>{{source.id==='personal'?'Личная доска':'Общая доска хранилища'}}</small></span><UIcon name="i-lucide-arrow-up-right"/></button></div></div>
    <p v-if="c.loading&&!c.displayData" class="kaban-loading" role="status">Загружаем доску…</p>
    <template v-else-if="c.displayData&&c.view==='history'">
     <div class="kaban-history-toolbar"><p class="kaban-help">Все изменения задач, категорий, стадий и вложений. Время указано по Москве.</p><UButton label="Обновить историю" icon="i-lucide-refresh-cw" color="neutral" variant="outline" :loading="c.historyLoading" @click="c.loadHistory()"/></div>
     <div class="kaban-history"><article v-for="event in c.history" :key="event.id"><PersonAvatar :name="event.actor?.fullName||'Система'" :src="event.actor?.avatarUrl"/><div><strong>{{event.label}}</strong><p v-for="detail in event.details" :key="detail">{{detail}}</p><small>{{event.actor?.fullName||event.actor?.email||'Система'}} · {{new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Moscow'}).format(new Date(event.createdAt))}}</small></div></article><p v-if="!c.history.length&&!c.historyLoading" class="kaban-help">Изменений пока нет.</p></div><UButton v-if="c.historyBefore" label="Показать ещё" color="neutral" variant="outline" :loading="c.historyLoading" @click="c.loadHistory(true)"/>
    </template>
    <template v-else-if="c.displayData">
     <section v-if="c.view==='closed'" class="kaban-closed-categories"><h2>Закрытые категории и подкатегории</h2><div v-for="category in c.displayData.categories.filter(category=>category.archived)" :key="(category.boardId||'')+category.id"><span><strong>{{category.boardId?c.sourceName(category.boardId)+' · ':''}}{{category.name}}</strong><small v-if="category.parentId">{{c.displayData.categories.find(parent=>parent.id===category.parentId)?.name}}</small></span><UButton v-if="c.displayData.canEdit" label="Восстановить" size="sm" color="neutral" variant="outline" :disabled="c.busy||!!c.displayData.categories.find(parent=>parent.id===category.parentId&&parent.archived)" @click="c.archiveCategory(category,false)"/></div><p v-if="!c.displayData.categories.some(category=>category.archived)" class="kaban-help">Закрытых категорий пока нет.</p></section>
     <div class="kaban-toolbar"><UInput v-model="c.search" icon="i-lucide-search" placeholder="Найти задачу…" aria-label="Поиск задач" class="flex-1"/><UButton color="neutral" :variant="c.onlyMine?'soft':'ghost'" label="Мои задачи" :aria-pressed="c.onlyMine" @click="c.onlyMine=!c.onlyMine"/><UButton color="neutral" :variant="c.onlyOverdue?'soft':'ghost'" label="Просроченные" :aria-pressed="c.onlyOverdue" @click="c.onlyOverdue=!c.onlyOverdue"/><UButton icon="i-lucide-refresh-cw" color="neutral" variant="ghost" aria-label="Обновить доску" :loading="c.loading" @click="c.load()"/></div>
     <UAlert v-if="!c.displayData.canEdit" title="Доступ только для просмотра" color="neutral" class="mb-4"/>
     <div v-if="c.workspaceId!=='all'&&c.view==='board'&&!c.categoryOptions.length" class="kaban-onboarding"><UIcon name="i-lucide-folder-plus"/><strong>Начните с категории</strong><p>{{c.canCategorize?'Создайте собственную категорию Кабана и добавляйте в неё подкатегории. Категории паролей здесь не используются.':'Попросите администратора хранилища создать категорию или открыть доступ к существующей.'}}</p><UButton v-if="c.canCategorize" label="Создать категорию" icon="i-lucide-plus" @click="c.editCategory()"/></div>
     <p v-if="c.workspaceId==='all'&&!c.tasks.length" class="kaban-loading">Нет задач по выбранным условиям.</p>
     <div class="kaban-board" aria-label="Канбан-доска">
      <section v-for="stage in c.boardStages" :key="stage.id" class="kaban-column" :class="{'is-drop-target':!!dragged}" @dragover.prevent @drop.prevent="drop(stage.id)">
       <header><span class="kaban-stage-dot" :style="{background:stage.color}"/><h2>{{stage.name}}</h2><span class="kaban-column-count">{{c.tasks.filter(task=>task.stageId===stage.id).length}}</span><UButton v-if="c.workspaceId!=='all'&&c.displayData.canEdit&&c.view==='board'" size="xs" icon="i-lucide-plus" color="neutral" variant="ghost" :aria-label="`Добавить задачу: ${stage.name}`" :disabled="c.busy" @click="c.openTask(undefined,stage.id)"/></header>
       <div class="kaban-column-body"><article v-for="task in c.tasks.filter(task=>task.stageId===stage.id)" :key="task.id" class="kaban-task-card" :class="{'is-overdue':c.kabanOverdue(task,stage.done),'is-done':stage.done}" :draggable="task.canEdit&&!c.busy&&!task.archived" @dragstart="event=>{dragged=task.id;if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',task.id)}}" @dragend="dragged=''">
        <button class="kaban-task-open" @click="c.openTask(task)"><span class="kaban-task-category">{{c.displayData.categories.filter(category=>task.categoryIds.includes(category.id)).map(category=>category.name).join(' · ')}}</span><small v-if="c.workspaceId==='all'||task.locations.length>1" class="kaban-task-sources">{{c.taskSourceNames(task)}}</small><strong>{{task.title}}</strong><p v-if="task.description">{{task.description}}</p></button>
        <div class="kaban-task-meta"><span v-if="task.dueOn" :class="{'is-overdue':c.kabanOverdue(task,stage.done)}"><UIcon name="i-lucide-calendar-days"/>{{c.dateLabel(task.dueOn)}}</span><span v-else><UIcon name="i-lucide-calendar-off"/>Без срока</span><span v-if="task.todos.length"><UIcon name="i-lucide-list-checks"/>{{task.todos.filter(item=>item.done).length}} / {{task.todos.length}}</span><span v-if="task.fileCount"><UIcon name="i-lucide-paperclip"/>{{task.fileCount}}</span></div>
        <progress v-if="task.todos.length" :value="task.todos.filter(item=>item.done).length" :max="task.todos.length" aria-label="Прогресс списка дел"/>
        <footer><UButton v-if="c.canComplete(task)" size="xs" :icon="task.archived?'i-lucide-archive-restore':'i-lucide-archive'" color="neutral" variant="ghost" :aria-label="`${task.archived?'Восстановить':'Закрыть'} задачу: ${task.title}`" :disabled="c.busy||(task.archived&&c.displayData.categories.some(category=>task.categoryIds.includes(category.id)&&category.archived))" :title="task.archived?'Сначала восстановите категорию задачи':'Закрыть задачу'" @click="c.archiveTask(task,!task.archived)"/><span :title="`Создатель: ${c.person(task.creatorId)?.fullName||'Участник'}`"><PersonAvatar :name="c.person(task.creatorId)?.fullName||'Участник'" :src="c.person(task.creatorId)?.avatarUrl"/><small>{{c.person(task.creatorId)?.fullName||'Участник'}}</small></span><span class="kaban-task-avatars"><PersonAvatar v-for="id in task.participantIds.slice(0,3)" :key="id" :name="c.person(id)?.fullName||'Участник'" :src="c.person(id)?.avatarUrl" :title="c.person(id)?.fullName"/><small v-if="task.participantIds.length>3">+{{task.participantIds.length-3}}</small></span></footer>
       </article><p v-if="!c.tasks.some(task=>task.stageId===stage.id)" class="kaban-column-empty">{{c.displayData.canEdit?'Перетащите задачу сюда или создайте новую':'Пока нет задач'}}</p></div>
      </section>
     </div>
    </template>
   </div>
  </main>
  <KabanTaskModal :controller="c"/>
  <UModal v-model:open="c.stagesOpen" title="Стадии доски" description="Порядок колонок, названия и завершённые стадии. Для удаления занятой стадии сначала перенесите из неё задачи." :dismissible="!c.busy" :ui="{content:'sm:max-w-3xl'}"><template #body><form :id="stageFormId" class="kaban-stage-editor" @submit.prevent="c.saveStages"><div v-for="(stage,index) in c.stageDraft" :key="stage.id" class="kaban-stage-edit-row"><UInput v-model="stage.name" :aria-label="`Название стадии ${index+1}`" :maxlength="60" required :disabled="c.busy" class="flex-1"/><input v-model="stage.color" type="color" :aria-label="`Цвет стадии ${index+1}`" :disabled="c.busy"/><UCheckbox v-model="stage.done" label="Готово" :disabled="c.busy"/><UButton type="button" icon="i-lucide-arrow-up" color="neutral" variant="ghost" :aria-label="`Поднять стадию ${index+1}`" :disabled="c.busy||index===0" @click="c.shiftStage(index,-1)"/><UButton type="button" icon="i-lucide-arrow-down" color="neutral" variant="ghost" :aria-label="`Опустить стадию ${index+1}`" :disabled="c.busy||index===c.stageDraft.length-1" @click="c.shiftStage(index,1)"/><UButton type="button" icon="i-lucide-trash-2" color="error" variant="ghost" :aria-label="`Удалить стадию ${stage.name}`" :disabled="c.busy||c.stageDraft.length<=1||c.stageCount(stage.id)>0" @click="c.stageDraft.splice(index,1)"/></div><UButton type="button" icon="i-lucide-plus" label="Добавить стадию" color="neutral" variant="outline" :disabled="c.busy||c.stageDraft.length>=12" @click="c.addStage"/><UAlert v-if="c.stageError" color="error" :description="c.stageError"/></form></template><template #footer><UButton label="Отмена" color="neutral" variant="outline" :disabled="c.busy" @click="c.stagesOpen=false"/><UButton type="submit" :form="stageFormId" label="Сохранить стадии" :loading="c.busy"/></template></UModal>
  <UModal v-model:open="c.categoryOpen" :title="c.categoryForm.id?'Изменить категорию':'Новая категория задач'" description="Своя категория Кабана. Можно сделать её подкатегорией другой категории." :dismissible="!c.structureBusy"><template #body><form :id="taskFormId" class="space-y-4" @submit.prevent="c.saveCategory"><UFormField label="Название" required><UInput v-model="c.categoryForm.name" :maxlength="60" required class="w-full"/></UFormField><UFormField label="Родительская категория"><USelect v-model="c.categoryParent" :items="c.parentOptions" class="w-full"/></UFormField><UFormField label="Цвет"><div class="flex gap-2"><button v-for="color in colors" :key="color" type="button" class="kaban-color-choice" :style="{background:color}" :aria-label="`Цвет ${color}`" :aria-pressed="c.categoryForm.color===color" @click="c.categoryForm.color=color"><UIcon v-if="c.categoryForm.color===color" name="i-lucide-check"/></button></div></UFormField><UAlert v-if="c.categoryError" color="error" :description="c.categoryError"/></form></template><template #footer><UButton label="Отмена" color="neutral" variant="outline" :disabled="c.structureBusy" @click="c.categoryOpen=false"/><UButton type="submit" :form="taskFormId" label="Сохранить категорию" :loading="c.structureBusy"/></template></UModal>
  <UModal :open="!!archiveTarget" title="Закрыть категорию?" description="Категория, её открытые подкатегории и задачи переместятся в «Закрытые задачи». Их можно восстановить." :dismissible="!c.busy" @update:open="value=>{if(!value)archiveTarget=null}"><template #body><p>{{archiveTarget?.name}}</p><UAlert v-if="c.error" color="error" :description="c.error"/></template><template #footer><UButton label="Отмена" color="neutral" variant="outline" :disabled="c.busy" @click="archiveTarget=null"/><UButton label="Закрыть категорию" :loading="c.busy" @click="async()=>{if(archiveTarget){await c.archiveCategory(archiveTarget,true);if(!c.error)archiveTarget=null}}"/></template></UModal>
 </div>
</template>
